mapper.select:

SELECT id, report_type, business_date, revision, status, model, prompt_version, data_as_of, collected_at,
  is_synthetic, algorithm_version, data_scope, input_hash
FROM analysis_report a
WHERE is_synthetic=#{synthetic}
  AND report_type=#{reportType}
  AND business_date BETWEEN #{startDate} AND #{endDate}
  AND (#{latestOnly}=FALSE
    OR NOT EXISTS(
    SELECT 1
    FROM analysis_report newer
    WHERE newer.report_type=a.report_type
      AND newer.business_date=a.business_date
      AND newer.is_synthetic=a.is_synthetic
      AND newer.revision>a.revision
  ))
ORDER BY business_date DESC, revision DESC
LIMIT #{size}
OFFSET #{offset}


SELECT COALESCE(MAX(revision), 0)+1
FROM analysis_report
WHERE report_type=#{type}
  AND business_date=#{date}
